INSERT INTO purpose VALUES('theory-stone-duality','error::DualityError','enum','Names why the duality refused an input: an index past its bound, a relation with a cycle, a map that breaks an order, an enumeration past its budget, or two opens that do not glue.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','finite::ElementSet','struct','Holds a set of at most 64 elements as one machine word, so a down-set or a member of a lattice of sets is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','finite::FinitePoset','struct','Holds a finite partial order as the down-set of each element, closed under transitivity, so the order and the lattice of its down-sets are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','finite::MonotoneMap','struct','Holds a monotone map between two finite posets, so the map''s images and its preimages of down-sets are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','finite::SetRing','struct','Holds a finite distributive lattice as a lattice of sets closed under union and intersection, so its members and its spectrum are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','finite::Spectrum','struct','Holds the join-irreducible members of a lattice of sets as a finite poset, so a member reads as a down-set of points and back.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::CubeMap','struct','Holds a monotone map between cubes of at most six axes as the image of each vertex, so the map''s dual homomorphism is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::Homomorphism','struct','Holds a homomorphism of free distributive lattices as the image of each generator, so substitution and the dual map of cubes are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::Polynomial','struct','Holds an element of a free distributive lattice in normal form, an antichain of terms, so its meet, join, order and truth table are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::Table','struct','Holds a truth table on a cube of at most six axes as one machine word, so a monotone function on the cube is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::Term','struct','Names a meet of generators as a bit set over the generators, so a term of a polynomial is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','free::Vertex','struct','Names a vertex of a cube as the set of axes at which it is one, so a point of the spectrum of a free lattice is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::Budget','struct','Names the most members an enumeration produces, so an exponential enumeration is refused past it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::Comparison','enum','Names whether one element lies below another in an order, so the order''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::Element','struct','Names an element of a finite poset or a point of a carrier, so the element''s position is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::ElementCount','struct','Names the number of elements of a finite poset or of points of a carrier, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::Generator','struct','Names a generator of a free distributive lattice, which is an axis of its cube, so the generator''s position is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::GeneratorCount','struct','Names the number of generators of a free distributive lattice, which is the number of axes of its cube.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::Membership','enum','Names whether a set holds an element or a polynomial holds at a vertex, so the membership''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::WIDEST','constant','Bounds the generators of a term and the elements of a finite poset by the bits of one machine word.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','index::WIDEST_CUBE','constant','Bounds the axes of a cube so that a truth table on it fits one machine word.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-stone-duality','pushout::Glued','struct','Holds the lattice that two lattices of sets glue to along an open of each, with the placement of each side''s points, so the restriction to each side is read.',NULL,'fits','sound',NULL);
